/**
 * A label under the slots of a line (`sb-chart__slots`): [text] over [span] points from the first of them (a month
 * over its weeks, G2a); "" keeps the place of a month too short for its word. The spans add up to the points.
 */
@Immutable
data class SbAxisLabel(val text: String, val span: Int = 1)

/**
 * One point of a line (G2a): [label] names it for TalkBack („Woche ab 03.08.“, the row head of the web's table),
 * [value] its place on the scale (null = no value: a gap, never bridged), [valueText] its number („6,1“; a gap needs
 * none, TalkBack says „keine Angabe“).
 */
@Immutable
data class SbLinePoint(val label: String, val value: Float?, val valueText: String = "")

/** One line of [SbSeriesChart] (G9a): [name] („Wasser“) and one point per slot, null = no value there (a gap). */
@Immutable
data class SbSeries(val name: String, val points: List<SbChartValue?>)

/** A label at a value beside the plot: [strong] = the latest value (title weight); [kept] = never left out. */
private class SbValueLabel(val value: Float, val text: String, val color: Color, val strong: Boolean, val kept: Boolean)

/**
 * Line, one series (G2a, spec/02 §3.7): one grey line (chartBar, 2 dp, round joins and caps) through the slot
 * centres in a 128 dp plot under one caption line of head room, the latest point with a value a 4 dp-radius dot in
 * chartBarCurrent; a null value splits the line (a gap, never bridged). [grid] lines 1 dp chartGrid, the [target]
 * 1 dp dashed textMuted, the base line 1 dp chartAxis at [from] (null = 0; with it the axis starts above 0 and its
 * number is written there). After the plot „Ziel n“, the latest value (text, title weight) and the grid and base
 * numbers (textMuted), each centred on its value; a number that would touch the target or the latest value is left
 * out. Under the plot the [axis] labels (one per point, or a month over its weeks). [max] = the top of the scale
 * (else the largest of the values, the target and the grid lines; a flat line at the base gets a scale of 1). At
 * least one point needs a value: with none yet, show SbEmptyState instead. TalkBack reads the caption, then one node
 * per point („Woche ab 03.08.: 6,1“; „keine Angabe“ for a gap), as the rows of the web's „Werte als Tabelle“.
 */
@Composable
fun SbLineChart(
    points: List<SbLinePoint>,
    caption: String,
    modifier: Modifier = Modifier,
    axis: List<SbAxisLabel> = emptyList(),
    target: SbChartValue? = null,
    grid: List<SbChartValue> = emptyList(),
    from: SbChartValue? = null,
    max: Float? = null,
) {
    require(points.size >= 2) { "SbLineChart: at least two points" }
    val latest = points.indexOfLast { it.value != null }
    require(latest >= 0) { "SbLineChart: no point has a value" }
    val now = points[latest]
    val nowValue = requireNotNull(now.value)
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val m = sbMessages()
    val bottom = from?.value ?: 0f
    // a flat line at the base (every value 0, no target, no grid) still draws, on the base line
    val top = max ?: listOfNotNull(points.maxOf { it.value ?: bottom }, target?.value, grid.maxOfOrNull { it.value }).max()
        .takeIf { it > bottom } ?: (bottom + 1f)
    require(top > bottom) { "SbLineChart: max must be above the start of the scale" }
    val ends = buildList {
        target?.let { add(SbValueLabel(it.value, m.chartTarget(it.text), c.textMuted, strong = false, kept = true)) }
        add(SbValueLabel(nowValue, now.valueText, c.text, strong = true, kept = true))
        grid.forEach { add(SbValueLabel(it.value, it.text, c.textMuted, strong = false, kept = false)) }
        from?.let { add(SbValueLabel(it.value, it.text, c.textMuted, strong = false, kept = false)) }
    }
    SbBoundedChartFigure(caption, modifier) {
        SbLinePlot(
            count = points.size,
            bottom = bottom,
            top = top,
            ticks = emptyList(),
            ends = ends,
            axis = axis,
            sentences = points.map { m.chartPoint(it.label, if (it.value == null) m.noValue else it.valueText) },
        ) { x, y ->
            val hair = t.borderWidth.hairline.toPx()
            grid.forEach { g -> drawLine(t.x.chartGrid, Offset(0f, y(g.value)), Offset(size.width, y(g.value)), hair) }
            target?.let { g ->
                val dash = t.space.s1.toPx()
                drawLine(
                    c.textMuted,
                    Offset(0f, y(g.value)),
                    Offset(size.width, y(g.value)),
                    hair,
                    pathEffect = PathEffect.dashPathEffect(floatArrayOf(dash, dash)),
                )
            }
            drawLine(t.x.chartAxis, Offset(0f, size.height - hair / 2f), Offset(size.width, size.height - hair / 2f), hair)
            val line = Stroke(width = t.x.chartLineWidth.toPx(), cap = StrokeCap.Round, join = StrokeJoin.Round)
            sbDrawLine(points.map { it.value }, x, y, t.x.chartBar, line)
            drawCircle(t.x.chartBarCurrent, radius = t.space.s1.toPx(), center = Offset(x(latest), y(nowValue)))
        }
    }
}

/**
 * Several series (G9a, spec/02 §3.7): 2 to 6 lines in SebaroTheme.dataviz.categorical in fixed order, each with its
 * own line style so they stay apart without colour (1 and 4 solid, 2 and 5 dashed 6 · 4, 3 and 6 dotted), one point
 * per [labels] entry (null = a gap). The [grid] and [from] numbers stand before the plot, the name and last value of
 * each series at its line end („Wasser 90 %“, text; ends that would touch move apart, the column takes at most half
 * the row or the widest word). From three series a legend above the plot (key with colour and line style, then the
 * name), in the order of the line ends from the top; two series have only the end labels. Once an end with its name
 * can no longer stand at its line (D101 (7), measured at every text size), the legend names the series, also two, and
 * each end keeps only its last value. Every series needs at least
 * one value (its end label shows the last); a flat chart at the base gets a scale of 1. TalkBack reads the caption,
 * the legend as one node („Legende, Wasser, …“), then one node per slot: „Woche ab 24.08.: Wasser 70 %,
 * Spaziergang 40 %, …“. It chooses the legend from its width (a BoxWithConstraints), so it cannot stand in a parent
 * that asks for intrinsic sizes (spec/08 §17).
 */
@Composable
fun SbSeriesChart(
    series: List<SbSeries>,
    labels: List<String>,
    caption: String,
    modifier: Modifier = Modifier,
    axis: List<SbAxisLabel> = emptyList(),
    grid: List<SbChartValue> = emptyList(),
    from: SbChartValue? = null,
    max: Float? = null,
) {
    require(series.size in 2..6) { "SbSeriesChart: 2 to 6 series (G9a); one series is SbLineChart" }
    require(labels.size >= 2) { "SbSeriesChart: at least two points" }
    require(series.all { it.points.size == labels.size }) { "SbSeriesChart: one point per label in every series" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val dv = SebaroTheme.dataviz
    val m = sbMessages()
    val last = series.map { s -> requireNotNull(s.points.lastOrNull { it != null }) { "SbSeriesChart: ${s.name} has no value" } }
    val bottom = from?.value ?: 0f
    val top = max ?: listOfNotNull(series.maxOf { s -> s.points.maxOf { it?.value ?: bottom } }, grid.maxOfOrNull { it.value }).max()
        .takeIf { it > bottom } ?: (bottom + 1f)
    require(top > bottom) { "SbSeriesChart: max must be above the start of the scale" }
    val named = series.mapIndexed { k, s -> SbValueLabel(last[k].value, s.name + " " + last[k].text, c.text, strong = false, kept = true) }
    val valued = series.mapIndexed { k, _ -> SbValueLabel(last[k].value, last[k].text, c.text, strong = false, kept = true) }
    val ticks = (grid + listOfNotNull(from)).map { SbValueLabel(it.value, it.text, c.textMuted, strong = false, kept = false) }
    // the legend in the order of the line ends from the top
    val order = series.indices.sortedByDescending { last[it].value }
    val measurer = rememberTextMeasurer()
    val ty = SebaroTheme.typography
    val labelStyle = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val fallback = 360.dp - t.spacing.gutter * 2
    BoxWithConstraints(modifier) {
        // D101 (7): the names stay at the line ends while each end, laid out as the plot lays it out, still covers the
        // height where its line ends (measured at every text size); else the legend names the series, also two, and
        // each end keeps only its last value
        val namesStand = with(LocalDensity.current) {
            val w = if (constraints.hasBoundedWidth) constraints.maxWidth else maxOf(constraints.minWidth, fallback.roundToPx())
            val gap = t.space.s2.roundToPx()
            val headPx = ty.caption.lineHeight.toDp().roundToPx()
            val base = headPx + (t.space.s16 * 2).roundToPx()
            fun widest(l: List<SbValueLabel>) = l.maxOf { ceil(measurer.measure(it.text, labelStyle).multiParagraph.intrinsics.minIntrinsicWidth).toInt() }
            fun layouts(l: List<SbValueLabel>, column: Int) = l.map { measurer.measure(it.text, labelStyle, constraints = Constraints(maxWidth = column)) }
            fun sizes(l: List<SbValueLabel>, column: Int) = layouts(l, column).map { it.size }
            val tickW = if (ticks.isEmpty()) 0 else {
                val column = sbLabelColumn(w, gap, widest(ticks))
                val sz = sizes(ticks, column)
                val spots = sbLabelSpots(ticks, IntArray(ticks.size) { sz[it].height }, bottom, top, headPx, base)
                spots.shown.maxOf { sz[it].width } + gap
            }
            val column = sbLabelColumn(w - tickW, gap, widest(named))
            val ends = layouts(named, column)
            val spots = sbLabelSpots(named, IntArray(named.size) { ends[it].size.height }, bottom, top, headPx, base)
            // each end on one line (a name wrapped away from its value no longer reads as the line's name; provisional,
            // agent) and over the height where its line ends
            named.indices.all { i ->
                val y = sbValueY(named[i].value, bottom, top, headPx, base)
                ends[i].lineCount == 1 && spots.tops[i] <= y && y <= spots.tops[i] + ends[i].size.height
            }
        }
        val legend = series.size >= 3 || !namesStand
        SbBoundedChartFigure(caption, legend = if (legend) ({ SbSeriesLegend(series, order) }) else null) {
            SbLinePlot(
                count = labels.size,
                bottom = bottom,
                top = top,
                ticks = ticks,
                ends = if (namesStand) named else valued,
                axis = axis,
                sentences = labels.mapIndexed { i, label ->
                    m.chartPoint(label, series.joinToString(", ") { s -> s.name + " " + (s.points[i]?.text ?: m.noValue) })
                },
            ) { x, y ->
                val hair = t.borderWidth.hairline.toPx()
                grid.forEach { g -> drawLine(t.x.chartGrid, Offset(0f, y(g.value)), Offset(size.width, y(g.value)), hair) }
                drawLine(t.x.chartAxis, Offset(0f, size.height - hair / 2f), Offset(size.width, size.height - hair / 2f), hair)
                series.forEachIndexed { k, s ->
                    sbDrawLine(s.points.map { it?.value }, x, y, dv.categorical[k], sbSeriesStroke(k, t.x.chartLineWidth.toPx()))
                }
            }
        }
    }
}

/** The legend of [SbSeriesChart] (`sb-chart__legend`): one key per series, colour and line style, then its name. */
@Composable
private fun SbSeriesLegend(series: List<SbSeries>, order: List<Int>) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val dv = SebaroTheme.dataviz
    val m = sbMessages()
    SbFlowRow(
        Modifier.clearAndSetSemantics { contentDescription = (listOf(m.chartLegend) + order.map { series[it].name }).joinToString(", ") },
        horizontalArrangement = Arrangement.spacedBy(t.space.s4),
        verticalArrangement = Arrangement.spacedBy(t.space.s1),
    ) {
        order.forEach { k ->
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(t.space.s2)) {
                Canvas(Modifier.size(t.size.iconLg, t.space.s2)) {
                    // the web's key: x 1 to 23 in a 24 wide box; names match no pooled import (TOOL-ISSUES CH1)
                    val edge = t.borderWidth.hairline.toPx()
                    val sample = Path().apply {
                        moveTo(edge, size.height / 2f)
                        lineTo(size.width - edge, size.height / 2f)
                    }
                    drawPath(sample, dv.categorical[k], style = sbSeriesStroke(k, t.x.chartLineWidth.toPx()))
                }
                Text(series[k].name, style = SebaroTheme.typography.caption, color = c.text)
            }
        }
    }
}

/** The line style of series [k] (`.sb-chart__line--1…6`): 1 and 4 solid, 2 and 5 dashed 6 · 4, 3 and 6 dotted. */
private fun DrawScope.sbSeriesStroke(k: Int, width: Float): Stroke = when (k % 3) {
    1 -> Stroke(width, cap = StrokeCap.Butt, join = StrokeJoin.Round, pathEffect = PathEffect.dashPathEffect(floatArrayOf(6.dp.toPx(), 4.dp.toPx())))
    2 -> Stroke(width, cap = StrokeCap.Round, join = StrokeJoin.Round, pathEffect = PathEffect.dashPathEffect(floatArrayOf(0f, 5.dp.toPx())))
    else -> Stroke(width, cap = StrokeCap.Round, join = StrokeJoin.Round)
}

/** A line through [values] at the slot centres; null splits it (a gap, never bridged); a lone point is a dot. */
private fun DrawScope.sbDrawLine(values: List<Float?>, x: (Int) -> Float, y: (Float) -> Float, color: Color, stroke: Stroke) {
    var i = 0
    while (i < values.size) {
        val first = values[i]
        if (first == null) {
            i++
            continue
        }
        var j = i
        while (j + 1 < values.size && values[j + 1] != null) j++
        if (j == i) {
            drawCircle(color, radius = stroke.width, center = Offset(x(i), y(first)))
        } else {
            val path = Path().apply {
                moveTo(x(i), y(first))
                for (k in i + 1..j) lineTo(x(k), y(requireNotNull(values[k])))
            }
            drawPath(path, color, style = stroke)
        }
        i = j + 1
    }
}

/**
 * [SbChartFigure] for the charts of §14.22–§14.24, which lay out by their width: when the parent sets no width (a
 * horizontally scrolling row, a LazyRow item without one) the figure is 328 dp wide, a 360 dp phone less its two
 * gutters, or the parent's minimum when that is wider; every other parent's width stays as it is. [modifier] sits on
 * this outer node, so a parent's weight or width reaches it. Provisional (agent): the web's figure always has its
 * container's width.
 */
@Composable
internal fun SbBoundedChartFigure(
    caption: String,
    modifier: Modifier = Modifier,
    legend: (@Composable () -> Unit)? = null,
    content: @Composable () -> Unit,
) {
    val fallback = 360.dp - SebaroTheme.tokens.spacing.gutter * 2
    Layout(
        content = { SbChartFigure(caption, legend = legend, content = content) },
        modifier = modifier,
    ) { measurables, constraints ->
        val inner = if (constraints.hasBoundedWidth) {
            constraints
        } else {
            val w = maxOf(constraints.minWidth, fallback.roundToPx())
            constraints.copy(minWidth = w, maxWidth = w)
        }
        val figure = measurables.first().measure(inner)
        layout(figure.width, figure.height) { figure.placeRelative(0, 0) }
    }
}

/**
 * The plot of a line (`sb-chart__plot`): [ticks] before it, a 128 dp area under one caption line of head room, [ends]
 * after it, the [axis] labels under it; [draw] gets the x of slot i (its centre, mirrored right to left) and the y of
 * a value. One TalkBack node per slot over its column, with its sentence from [sentences]. The last axis label may
 * run on under the end labels (as on the web) only while no end label hangs below the base line there.
 */
@Composable
private fun SbLinePlot(
    count: Int,
    bottom: Float,
    top: Float,
    ticks: List<SbValueLabel>,
    ends: List<SbValueLabel>,
    axis: List<SbAxisLabel>,
    sentences: List<String>,
    draw: DrawScope.(x: (Int) -> Float, y: (Float) -> Float) -> Unit,
) {
    val t = SebaroTheme.tokens
    val plot = t.space.s16 * 2
    val head = with(LocalDensity.current) { SebaroTheme.typography.caption.lineHeight.toDp() }
    Layout(
        content = {
            SbValueLabels(ticks, bottom, top, head, plot, before = true)
            Box {
                Canvas(Modifier.matchParentSize()) {
                    val rtl = layoutDirection == LayoutDirection.Rtl
                    draw(
                        { i -> size.width * (if (rtl) count - i - 0.5f else i + 0.5f) / count },
                        { v -> size.height * (1f - ((v - bottom) / (top - bottom)).coerceIn(0f, 1f)) },
                    )
                }
                // the web's „Werte als Tabelle“ for TalkBack: one node per slot, over its column of the plot
                Row(Modifier.matchParentSize()) {
                    sentences.forEach { s ->
                        Box(
                            Modifier
                                .weight(1f)
                                .fillMaxHeight()
                                .semantics(mergeDescendants = true) { contentDescription = s },
                        )
                    }
                }
            }
            SbValueLabels(ends, bottom, top, head, plot, before = false)
            SbAxisLabels(axis, count)
        },
        modifier = Modifier.fillMaxWidth(),
    ) { measurables, constraints ->
        val w = constraints.maxWidth
        val headPx = head.roundToPx()
        val base = headPx + plot.roundToPx()
        val tickP = measurables[0].measure(Constraints(maxWidth = w))
        val endP = measurables[2].measure(Constraints(maxWidth = w - tickP.width))
        val areaW = (w - tickP.width - endP.width).coerceAtLeast(0)
        val areaP = measurables[1].measure(Constraints.fixed(areaW, base - headPx))
        // the axis labels get the plot's width as their minimum and the room they may run into as their maximum
        val axisP = measurables[3].measure(Constraints(minWidth = areaW, maxWidth = if (endP.height > base) areaW else areaW + endP.width))
        layout(w, maxOf(base + axisP.height, tickP.height, endP.height)) {
            tickP.placeRelative(0, 0)
            areaP.placeRelative(tickP.width, headPx)
            endP.placeRelative(tickP.width + areaW, 0)
            axisP.placeRelative(tickP.width, base)
        }
    }
}

/**
 * Labels at values beside the plot (`sb-chart__ticks` before it, end-aligned; `sb-chart__ends` after it), 8 dp from
 * it, each centred on its value, at most half the row wide or as wide as the widest word (a longer label wraps
 * between words, never inside one).
 * Kept labels move apart when they would touch, never above the top, and below the base line only when there is no
 * room left; any other label that would touch one is left out. As tall as its lowest label. Hidden from TalkBack.
 */
@Composable
private fun SbValueLabels(labels: List<SbValueLabel>, bottom: Float, top: Float, head: Dp, plot: Dp, before: Boolean) {
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    Layout(
        content = {
            labels.forEach { l ->
                Text(
                    l.text,
                    style = if (l.strong) text.copy(fontWeight = ty.title.fontWeight) else text,
                    color = l.color,
                    textAlign = if (before) TextAlign.End else TextAlign.Start,
                )
            }
        },
        modifier = Modifier.clearAndSetSemantics { },
    ) { measurables, constraints ->
        if (labels.isEmpty()) return@Layout layout(0, 0) { }
        val gap = t.space.s2.roundToPx()
        val column = sbLabelColumn(constraints.maxWidth, gap, measurables.maxOf { it.minIntrinsicWidth(Constraints.Infinity) })
        val placeables = measurables.map { it.measure(Constraints(maxWidth = column)) }
        val headPx = head.roundToPx()
        val base = headPx + plot.roundToPx()
        val spots = sbLabelSpots(labels, IntArray(labels.size) { placeables[it].height }, bottom, top, headPx, base)
        val inner = spots.shown.maxOf { placeables[it].width }
        val height = maxOf(base.toFloat(), spots.shown.maxOf { spots.tops[it] + placeables[it].height })
        layout(inner + gap, height.roundToInt()) {
            spots.shown.forEach { i ->
                val p = placeables[i]
                p.placeRelative(if (before) inner - p.width else gap, spots.tops[i].roundToInt())
            }
        }
    }
}

/** The width of a label column beside the plot: half the row less the gap, or the widest word of any label if wider. */
private fun sbLabelColumn(row: Int, gap: Int, widestWord: Int): Int {
    val room = (row - gap).coerceAtLeast(0)
    return maxOf(room / 2, widestWord).coerceAtMost(room)
}

/** The labels a column shows ([shown], kept ones first) and the top of each ([tops], px from the head room's top). */
private class SbLabelSpots(val shown: List<Int>, val tops: FloatArray)

/**
 * Where the labels at values stand, from their [heights] at the column's width: each centred on its value; kept
 * labels move apart when they would touch, never above the top, and below the base line only when there is no room
 * left; any other label that would touch one is left out. [headPx] is the head room, [base] the base line.
 */
private fun sbLabelSpots(labels: List<SbValueLabel>, heights: IntArray, bottom: Float, top: Float, headPx: Int, base: Int): SbLabelSpots {
    val tops = FloatArray(labels.size) { i -> sbValueY(labels[i].value, bottom, top, headPx, base) - heights[i] / 2f }
    val kept = labels.indices.filter { labels[it].kept }.sortedBy { tops[it] }
    var floor = 0f
    for (i in kept) {
        tops[i] = maxOf(tops[i], floor)
        floor = tops[i] + heights[i]
    }
    for (n in kept.indices.reversed()) {
        val i = kept[n]
        val limit = if (n == kept.lastIndex) base + heights[i] / 2f else tops[kept[n + 1]]
        val ceiling = if (n == 0) 0f else tops[kept[n - 1]] + heights[kept[n - 1]]
        tops[i] = maxOf(ceiling, minOf(tops[i], limit - heights[i]))
    }
    val shown = kept.toMutableList()
    labels.indices.filter { !labels[it].kept }.forEach { i ->
        val touches = shown.any { j -> tops[i] < tops[j] + heights[j] && tops[j] < tops[i] + heights[i] }
        if (!touches) shown += i
    }
    return SbLabelSpots(shown, tops)
}

/** The y of [value] on the plot, px from the head room's top: the plot runs from [headPx] (top) to [base] (bottom). */
private fun sbValueY(value: Float, bottom: Float, top: Float, headPx: Int, base: Int): Float =
    headPx + (base - headPx) * (1f - ((value - bottom) / (top - bottom)).coerceIn(0f, 1f))

/**
 * The labels under a line's slots (`sb-chart__slots`), 4 dp under the plot: centred on their slot, or start-aligned
 * over their span when any label spans several points (`--start`). The minimum width is the plot's, the maximum the
 * room the last label may run into; read from the end, a label that would run past that room or into the next label
 * shown is left out.
 * Hidden from TalkBack (the slot nodes name every point).
 */
@Composable
private fun SbAxisLabels(axis: List<SbAxisLabel>, count: Int) {
    require(axis.isEmpty() || (axis.all { it.span >= 1 } && axis.sumOf { it.span } == count)) {
        "SbAxisLabel: the spans add up to the points"
    }
    val ty = SebaroTheme.typography
    val text = ty.caption.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings)
    val start = axis.any { it.span > 1 }
    val above = SebaroTheme.tokens.space.s1
    Layout(
        content = { axis.forEach { Text(it.text, style = text, color = SebaroTheme.colors.textMuted, maxLines = 1, softWrap = false) } },
        modifier = Modifier.clearAndSetSemantics { },
    ) { measurables, constraints ->
        if (axis.isEmpty()) return@Layout layout(constraints.minWidth, 0) { }
        val placeables = measurables.map { it.measure(Constraints()) }
        val slot = constraints.minWidth.toFloat() / count
        var at = 0
        val xs = axis.mapIndexed { i, a ->
            val x = if (start) at * slot else at * slot + (slot * a.span - placeables[i].width) / 2f
            at += a.span
            x
        }
        // from the end: a label stays when it ends inside the room and before the next label shown, so the latest
        // labels win and none is dropped for a label that is dropped itself
        val shown = mutableListOf<Int>()
        var limit = constraints.maxWidth.toFloat()
        for (i in axis.indices.reversed()) {
            if (axis[i].text.isEmpty()) continue
            if (xs[i] + placeables[i].width <= limit) {
                shown += i
                limit = xs[i]
            }
        }
        val y = above.roundToPx()
        layout(constraints.minWidth, y + placeables.maxOf { it.height }) {
            shown.forEach { i -> placeables[i].placeRelative(xs[i].roundToInt(), y) }
        }
    }
}
